const fs = require('fs'); const path = require('path'); const { fresh, t, tree } = require('./h.cjs');
const d = fresh('w-new'); fs.writeFileSync(`${d}/a`, 'abcdef');
t('copyFileSync', () => { fs.copyFileSync(`${d}/a`, `${d}/b`); return fs.readFileSync(`${d}/b`, 'utf8'); });
t('copyFileSync EXCL existing', () => fs.copyFileSync(`${d}/a`, `${d}/b`, fs.constants.COPYFILE_EXCL));
t('copyFileSync EXCL new', () => fs.copyFileSync(`${d}/a`, `${d}/c`, fs.constants.COPYFILE_EXCL));
t('copyFileSync missing', () => fs.copyFileSync(`${d}/zz`, `${d}/b`));
t('copyFileSync dir src', () => fs.copyFileSync(d, `${d}/dd`));
t('copyFileSync into missing dir', () => fs.copyFileSync(`${d}/a`, `${d}/no/b`));
t('copyFileSync bad mode', () => fs.copyFileSync(`${d}/a`, `${d}/b`, 99));
t('truncateSync 3', () => { fs.truncateSync(`${d}/b`, 3); return fs.readFileSync(`${d}/b`, 'utf8'); });
t('truncateSync grow 5', () => { fs.truncateSync(`${d}/b`, 5); return [...fs.readFileSync(`${d}/b`)]; });
t('truncateSync default', () => { fs.truncateSync(`${d}/b`); return fs.statSync(`${d}/b`).size; });
t('truncateSync missing', () => fs.truncateSync(`${d}/zz`, 1));
t('truncateSync dir', () => fs.truncateSync(d, 1));
t('truncateSync negative', () => fs.truncateSync(`${d}/a`, -1));
t('ftruncateSync', () => { const fd = fs.openSync(`${d}/c`, 'r+'); fs.ftruncateSync(fd, 2); fs.closeSync(fd); return fs.readFileSync(`${d}/c`, 'utf8'); });
t('mkdtempSync', () => { const p = fs.mkdtempSync(`${d}/tmp-`); return [path.basename(p).length, p.startsWith(`${d}/tmp-`), fs.statSync(p).isDirectory()]; });
t('mkdtempSync missing parent', () => fs.mkdtempSync(`${d}/no/tmp-`));
t('mkdtempSync buffer', () => Buffer.isBuffer(fs.mkdtempSync(`${d}/b-`, { encoding: 'buffer' })));
t('mkdtempSync unique', () => new Set(Array.from({ length: 20 }, () => fs.mkdtempSync(`${d}/u-`))).size);
fs.mkdirSync(`${d}/od/x`, { recursive: true }); fs.writeFileSync(`${d}/od/f1`, '1'); fs.writeFileSync(`${d}/od/x/f2`, '2');
t('opendirSync readSync', () => { const dir = fs.opendirSync(`${d}/od`); const o = []; let e; while ((e = dir.readSync())) o.push(`${e.name}:${e.isDirectory()}:${e.parentPath}`); dir.closeSync(); return [dir.path, o.sort()]; });
t('opendirSync recursive', () => { const dir = fs.opendirSync(`${d}/od`, { recursive: true }); const o = []; let e; while ((e = dir.readSync())) o.push(path.join(e.parentPath, e.name)); dir.closeSync(); return o.sort(); });
t('opendirSync missing', () => fs.opendirSync(`${d}/nope`));
t('opendirSync file', () => fs.opendirSync(`${d}/a`));
t('opendirSync closed twice', () => { const dir = fs.opendirSync(`${d}/od`); dir.closeSync(); dir.closeSync(); });
(async () => { const dir = fs.opendirSync(`${d}/od`); const o = []; for await (const e of dir) o.push(e.name); console.log('opendir for-await', o.sort()); try { dir.closeSync(); } catch (e) { console.log('close after iteration', e.code); } })();
t('cpSync file', () => { fs.cpSync(`${d}/a`, `${d}/cp1`); return fs.readFileSync(`${d}/cp1`, 'utf8'); });
t('cpSync dir recursive', () => { fs.cpSync(`${d}/od`, `${d}/od2`, { recursive: true }); return tree(`${d}/od2`); });
t('cpSync into existing dir merges', () => { fs.writeFileSync(`${d}/od2/extra`, 'e'); fs.cpSync(`${d}/od`, `${d}/od2`, { recursive: true }); return tree(`${d}/od2`); });
t('cpSync file onto dir', () => fs.cpSync(`${d}/a`, `${d}/od2`));
t('cpSync dir onto file', () => fs.cpSync(`${d}/od`, `${d}/a`, { recursive: true }));
t('chmodSync missing', () => fs.chmodSync(`${d}/zz`, 0o644)); t('chmodSync ok', () => fs.chmodSync(`${d}/a`, 0o644));
t('utimesSync missing', () => fs.utimesSync(`${d}/zz`, 1, 1)); t('chownSync missing', () => fs.chownSync(`${d}/zz`, 0, 0));
t('fsyncSync bad fd', () => fs.fsyncSync(9999));
t('mkdirSync recursive return', () => [fs.mkdirSync(`${d}/m1/m2/m3`, { recursive: true }), fs.mkdirSync(`${d}/m1/m2`, { recursive: true }), fs.mkdirSync(`./${d}/r1/r2`, { recursive: true })]);
t('mkdirSync exists', () => fs.mkdirSync(`${d}/m1`));
t('fs.mkdir no callback', () => fs.mkdir(`${d}/zzz`, {}));
